const D = { energy: .58, scale: 1, density: .5, track: .6, hue: 38, speed: 1, x: .5, y: .5, alpha: .9, style: 'print', act: 'run', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const ss=(e0,e1,x)=>{let t=(x-e0)/(e1-e0); t=t<0?0:t>1?1:t; return t*t*(3-2*t);};
const bnd=(a,b,x,s)=>ss(a-s,a+s,x)*(1-ss(b-s,b+s,x));           // soft band membership
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const ih=(x,y)=>{ let h=(Math.imul(x|0,374761393)+Math.imul(y|0,668265263)+Math.imul(P.seed|0,1274126177))|0;
  h=Math.imul(h^(h>>>13),1274126177); h=(h^(h>>>16))>>>0; return h/4294967296; };
const hsb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255|0,(g+m)*255|0,(l+m)*255|0]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh), dc=drawingContext, oldOp=dc.globalCompositeOperation;
const styN=P.style, act=P.act;
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dns=cl(P.density,0,1), tk=cl(P.track,0,1);
const H0=md(P.hue,360), spd=cl(P.speed,.1,4), al=cl(P.alpha,0,1);
const ax=cl(P.x,0,1), ay=cl(P.y,0,1);
const T=K.t*spd;
const MODE = styN==='negative'?1 : styN==='academy'?2 : styN==='super8'?3 : styN==='contact'?4 : 0;

S.rms=(S.rms||0)*.90+(A.rms||0)*.10;
S.low=(S.low||0)*.90+(A.lowmid||0)*.10;

// ---- dramaturgy over minutes ----
let crRate=.0785, wear=dns, splice=0;
if(act==='creep'){ crRate=.031; }
else if(act==='reel_end'){
  const q=md(K.t*.0062,1);                                  // ~160s reel
  wear=cl(dns*(.45+1.25*q),0,1); crRate=.0785+.042*q;
  splice=ss(.955,.975,q)*(1-ss(.988,.998,q));               // a splice passes near the end, then a fresh reel
}
// A pure linear creep is still PERIODIC in appearance (period = one frame pitch),
// so it re-phases whenever 8s*rate lands near a whole frame — that is exactly the
// silent killer. Rates are chosen off that resonance AND the creep wanders on slow
// incommensurate terms so the 8s phase relationship never repeats.
const creep=T*crRate + .27*Math.sin(K.t*.0367) + .16*Math.sin(K.t*.0831+1.1)
          + .09*Math.sin(K.t*.1913+2.7) + .012*Math.sin(K.t*.53);

// ---- film geometry, in strip-normalised coordinates ----
const scMul = MODE===4?.46 : 1;
const sw = W*.98*sc*scMul;
// pitch follows the film width, but is clamped so a frame line still travels the
// gate at big blow-ups (otherwise scale-max leaves a bare lit field that barely moves)
const pitch = Math.min(sw*(MODE===3?.74:MODE===4?.78:.75), Hh*1.55);
const sx0 = ax*W - sw*.5;
// perf columns / soundtrack / picture window vary by gauge
let pcL0=.030,pcL1=.098, pcR0=.902,pcR1=.970, tr0=.112,tr1=.178, pi0=.196,pi1=.892, perfN=4, twoSide=1;
if(MODE===3){ pcL0=.022; pcL1=.070; twoSide=0; tr0=-1; tr1=-1; pi0=.100; pi1=.980; perfN=1; }
else if(MODE===1){ tr0=-1; tr1=-1; pi0=.130; pi1=.878; }
else if(MODE===4){ tr0=-1; tr1=-1; pi0=.126; pi1=.874; }
else if(MODE===2){ tr0=.106; tr1=.186; pi0=.204; pi1=.886; }
const hasTrack = tr0>0;

const LA=Math.max(360,Math.min(720,Math.round(Math.max(W,Hh)/2.4))); let GW,GH;
if(W>=Hh){ GW=LA; GH=Math.max(64,Math.round(LA*Hh/Math.max(1,W))); }
else { GH=LA; GW=Math.max(64,Math.round(LA*W/Math.max(1,Hh))); }
const gk=GW+'x'+GH;
if(!S.eB||S.gk!==gk){
