const hsx=.34*Math.sin(K.t*.043)+.21*Math.sin(K.t*.109+1.9);
const hsy=.29*Math.sin(K.t*.061+.7)+.17*Math.sin(K.t*.137+2.4);
const lampJ=1+.022*Math.sin(K.t*.77)+.013*Math.sin(K.t*1.83);     // lamp ripple, never a flash
const gain=(.52+.80*en)*al*lampJ*(1+.09*S.rms);
const soft=.006+.010/Math.max(.35,sc);

