const cBase = MODE===1 ? hsb(26,78,100) : hsb(md(H0+14,360),30,100);
const cFog  = hsb(md(H0+8,360),34,100);
const baseEmit = MODE===1 ? .30 : MODE===4 ? .14 : .035;          // orange negative mask passes light; a print rebate does not

for(let j=0;j<GH;j++){
  const py=(j+.5)/GH*Hh;
  const fy=(py-ay*Hh)/pitch + creep;
  const cell=fy-Math.floor(fy);
  const fIdx=Math.floor(fy);
  // frame line between cells: a full-width bar drifting through the gate
  const line=1-bnd(.052,.948,cell,.012);
  const pf=fy*perfN; const pcell=pf-Math.floor(pf);
  const perfY=bnd(.30,.70,pcell,.055);
  for(let i=0;i<GW;i++){
    const px=(i+.5)/GW*W;
    const fx=(px-sx0)/sw;
    const o=(j*GW+i)*4;
    const onStrip=bnd(-.002,1.002,fx,.004);

    const dxn=(px-ax*W)/(u*.5), dyn=(py-ay*Hh)/(u*.5);
    const hd2=(dxn-hsx)*(dxn-hsx)+(dyn-hsy)*(dyn-hsy);
    const lamp=(.58+.62*Math.exp(-hd2*1.05)-.10*(dxn*dxn+dyn*dyn));

    const inPic=bnd(pi0,pi1,fx,soft)*(1-line);
    const perfX=bnd(pcL0,pcL1,fx,soft) + (twoSide?bnd(pcR0,pcR1,fx,soft):0);
    const perf=cl(perfX*perfY,0,1);
    const inTrack=hasTrack?bnd(tr0,tr1,fx,soft):0;

    // optical soundtrack: variable-area, printed on the film so it scrolls with it
    let trk=0;
    if(inTrack>0){
      const wv=.50+.50*(Math.sin(fy*57.3)*.46+Math.sin(fy*131.7+1.1)*.30+Math.sin(fy*283.1+2.3)*.24);
      const amp=cl(wv*(.55+.75*tk)*(1+.55*S.low),0,1);
      const c0=(tr0+tr1)*.5, hw=(tr1-tr0)*.5*amp;
      trk=inTrack*bnd(c0-hw,c0+hw,fx,soft*.7);
    }

    // rebate = film base between the picture and the edges
    const rebate=cl(onStrip-inPic-perf-inTrack,0,1);

    // ---- emission: light through the gate, the holes and the base ----
    let e = inPic*(MODE===1?.34:.26) + perf*1.15 + trk*.92 + rebate*baseEmit + inTrack*.05;
    e += line*onStrip*.02;
    e *= lamp*gain;
    // edge fog + wear creeping in from the film's edges
    const edgeF=(1-bnd(.045,.955,fx,.05))*onStrip;
    const dirt=ih(Math.floor(fx*90),Math.floor(fy*140))*wear;
    e += edgeF*lamp*gain*(.06+.16*wear)*(.6+.7*dirt);
    if(splice>0){ const sd=Math.abs(cell-.5); e += splice*onStrip*ss(.30,.10,sd)*lamp*gain*.30; }

    let cR,cG,cB;
    if(rebate>.5 && MODE===1){ cR=cBase[0]; cG=cBase[1]; cB=cBase[2]; }
